  builder_.add_AGGRESSOR_ENDPOINT(AGGRESSOR_ENDPOINT);
  builder_.add_VICTIM_ENDPOINT(VICTIM_ENDPOINT);
  builder_.add_RFL_ID(RFL_ID);
  builder_.add_SCENARIO_ID(SCENARIO_ID);
